<?php $root='../';$title='Cek Status';include '../includes/header.php';$r=null;if(!empty($_GET['no']))$r=row('SELECT p.*,l.nama layanan FROM pengajuan_layanan p JOIN layanan l ON l.id=p.layanan_id WHERE nomor=?',[trim($_GET['no'])]);?>
<div class="container" style="max-width:600px"><h2 class="judul">Cek Status Pengajuan Surat</h2><form class="card-desa bg-white p-4 mb-3"><input name="no" class="form-control mb-2" placeholder="Nomor Pengajuan" value="<?=e($_GET['no']??'')?>"><button class="btn btn-hijau">Cek</button></form>
